# Proceedings of the 2015 Fur Trade Symposium: Bent's Fort and the Southern Fur Trade (La Junta, Colorado, 23-26 sept. 2015 ;
# Bent's Old Fort National Historic Site, 2016), PDF fourni par l'auteur de l'atlas le 19 novembre 2026. Corpus « Recherches »,
# préfixe FT15. Articles de B. Barbour (le whisky à Fort Laramie), M. Schaubs (l'inventaire de Fort Jackson, 1837), J. Hardee
# (les « Taos trappers » et la fin des rendez-vous) et J. A. Hanson (Chouteau et Bent, St. Vrain & Co.). Résumés rédigés par l'atlas.
from commun import Corpus
SY = "Proceedings of the 2015 Fur Trade Symposium: Bent's Fort and the Southern Fur Trade, La Junta (Colorado), Bent's Old Fort National Historic Site, 2016"
BB = f"Barbour, Barton, « The Trade and Intercourse Laws, Fur Traders, and the US Government », dans {SY}"
MS = f"Schaubs, Michael, « The 1837 Fort Jackson Trading Camp Inventory », dans {SY}"
JH = f"Hardee, Jim, « \"Taos Trappers\" and the Demise of the Rocky Mountain Rendezvous », dans {SY}"
C = Corpus('Recherches', 'FT15', SY, page_fmt='p. {}')
F = C.F
F('01', "Fort Platte : le whisky de Pratte & Cabanné sous la gérance de « M. Bissonnette » (1843)", 'commerce', '1843-09/1844', -104.55, 42.21, 'a', ['Joseph Bissonette', 'John Richard', 'Oliver Sarpy', 'Jean-Pierre Cabanné', 'Andrew Drips'],
  "En 1843, le poste de Fort Platte, sur la North Platte près de Fort Laramie, appartient à Pratte & Cabanné ; il est géré par « M. Bissonnette », avec John Richard parmi ses employés. Le 7 septembre, trois témoins, dont Oliver Sarpy, écrivent à l'agent Andrew Drips qu'ils ont vu une caravane y déposer quelque 300 gallons d'alcool et qu'on y vend ou donne du whisky aux Sioux brûlés ; Sarpy réclame la moitié des biens confisqués promise aux dénonciateurs par la loi. L'agent adjoint Hamilton fouille le poste sans rien trouver ; l'hiver suivant, un tonnelet envoyé par un traiteur de Pratte & Cabanné dans un camp oglala fait deux morts.",
  None, "Position à Fort Platte, au confluent de la Laramie et de la North Platte.", source=BB)
F('02', "Fort Pierre : les 300 gallons de « M. Reachard » et les six morts sioux (juillet 1843)", 'evenement', '1843-07', -100.38, 44.38, 'a', ['John Richard', 'Andrew Drips', 'Joseph Jouette'],
  "En juillet 1843, l'agent Hamilton apprend à Fort Pierre qu'« une grande quantité de liqueurs spiritueuses (environ 300 gallons) » vient d'arriver sous la garde d'un « M. Reachard » (John Richard), associé de Pratte & Cabanné dans la traite, que les Indiens boivent à l'excès et que six d'entre eux ont été tués. Drips écrit en janvier 1843 que l'alcool a déjà causé la mort de « quelque cent de leurs meilleures gens » chez les Sioux de Fort Pierre. À la fin de l'été, Hamilton part pour la Platte avec Joseph Jouette, interprète de Drips et employé de la compagnie Chouteau.",
  None, "Position à Fort Pierre (Dakota du Sud).", source=BB)
F('03', "Fort John (Fort Laramie) : Pierre D. Papin, Honoré Picotte et le contrat de « commis traiteur » de Drips (1842-1848)", 'poste', '1842/1848-08', -104.56, 42.20, 'c', ['Pierre D. Papin', 'Honoré Picotte', 'Andrew Drips', 'Alexander Culbertson', 'John Sarpy'],
  "Après l'achat de Fort William par la compagnie Chouteau, rebâti et rebaptisé Fort John, le bourgeois du poste est Pierre D. Papin ; la correspondance de la compagnie, souvent en français (John Sarpy écrit à Pierre Chouteau Jr., son « cher cousin »), passe par Fort Pierre, où commande Honoré Picotte. Le 6 avril 1847, l'ancien agent Andrew Drips signe un engagement de « commis traiteur » à « cent piastres par mois ». En août 1848, Picotte et Papin quittent la compagnie réorganisée, Culbertson prend Fort Pierre et Drips reçoit une part et la direction de Fort John.",
  None, "Position à Fort Laramie (Wyoming).", source=BB)
F('04', "Rivière Kansas : mort de l'engagé Michel Dubray près du poste de J. Papin (17 septembre 1844)", 'evenement', '1844-09-17', -95.67, 39.06, 'a', ['Michel Dubray', 'David Adams', 'Lancaster Lupton', 'J. Roubedow', 'J. Papin'],
  "En septembre 1844, la caravane de David Adams (Sibille & Adams), qui voyage avec celle de Lancaster Lupton vers la Platte, compte plusieurs malades de la fièvre, dont « J. Roubedow ». L'engagé Michel Dubray meurt le 17 septembre d'une « fièvre nerveuse » près du poste de J. Papin sur la Kansas (Caw), après cinq jours d'agonie : Adams avait en vain demandé aux habitants d'une maison voisine de l'abriter pour qu'il ne meure pas « tout seul comme un loup ».",
  None, "Position approximative au poste Papin, près de l'actuelle Topeka.", source=BB)
F('05', "Fort Jackson (South Platte) : Peter Sarpy, Henry Fraeb et l'inventaire de 1837", 'poste', '1837/1838', -104.75, 40.22, 'c', ['Peter Sarpy', 'Henry Fraeb', 'Charles Autobees', 'Simeon Turley'],
  "En 1837, pour contrer Fort Vasquez, ouvert en 1835 par Louis Vasquez et Andrew Sublette, la compagnie Chouteau fait bâtir Fort Jackson sur la South Platte, confié à Peter Sarpy et Henry Fraeb ; quatre postes se trouvent alors sur quinze milles de rivière. L'inventaire du camp de traite de 1837 est l'un des rares conservés pour la traite des Plaines. Un document montre que Sarpy et Fraeb paient le 1er mars 1838 treize dollars à « Charles Ottabees » (Autobees), qui vendait pour Simeon Turley le whisky et la farine de Taos dans les postes de la Platte. En 1838, Bent, St. Vrain & Co. rachète Fort Jackson, qui est ensuite détruit.",
  None, "Position à Fort Jackson, près de l'actuelle Ione (Colorado).", source=MS)
F('06', "Fort Uintah, le « rendez-vous de Robidoux » : Chalifoux, Bill Williams et Peg-leg Smith (1839-1840)", 'poste', '1839-09/1840-03', -109.98, 40.43, 'c', ['Antoine Robidoux', 'Jean-Baptiste Chalifoux', 'Bill Williams', 'Thomas L. Smith', 'Joe Meek', 'Robert Newell', 'Kit Carson'],
  "À la fin des rendez-vous, tant de trappeurs se réunissent autour du fort Uintah qu'on l'appelle parfois « le rendez-vous de Robidoux ». À l'automne 1839 s'y trouvent Bill Williams, Peg-leg Smith, « Jean B. Charlefou » (Chalifoux) et Frederick « Cut Nose » ; au printemps 1840, une dizaine d'entre eux partent voler des chevaux en Californie. Kit Carson et Jack Robinson y viennent vendre leurs fourrures au lieu d'aller au rendez-vous de la Green. Près de l'embouchure de l'Uintah, Meek et Newell sont rejoints par Antoine Robidoux, venu de Santa Fe avec des marchandises ; selon Meek, Robidoux, passionné du jeu de mains, perd au jeu ses marchandises, ses chevaux et même sa femme, et rentre à Santa Fe endetté.",
  None, "Position au fort Uintah (Fort Robidoux), près de Whiterocks (Utah).", source=JH)
F('07', "Bassin de l'Uinta : « M. Robidoux » et le « fort Kit Carson » de Richard Bland Lee (hiver 1833-1834)", 'poste', '1833-11~/1834-03~', -109.9, 40.3, 'a', ['Louis Robidoux', 'Antoine Robidoux', 'Kit Carson', 'Richard Bland Lee'],
  "À l'hiver 1833-1834, Kit Carson conduit dans le bassin de l'Uinta le groupe de Richard Bland Lee, officier en congé ; ils y trouvent « M. Robidoux » et une vingtaine de trappeurs déjà en quartiers d'hiver, et bâtissent à leur tour des cabanes, le futur « fort Kit Carson ». Hardee pense, d'après Willoughby, qu'il s'agit plutôt de Louis Robidoux, Antoine étant alors à Santa Fe pour affaires.",
  None, "Position approximative dans le bassin de l'Uinta.", source=JH)
F('08', "Confluent de l'Uinta et de la Whiterocks : le poste de William Reed et Denis Julien (1828)", 'poste', '1828/1831', -109.98, 40.43, 'a', ['Denis Julien', 'William Reed', 'Antoine Robidoux'],
  "En 1828, William Reed et Denis Julien remontent de Taos pour trapper et traiter avec les Utes et bâtissent un poste au confluent de l'Uintah et de la Whiterocks : le premier poste de traite du bassin. Après avoir vendu en 1831 à Santa Fe une grosse cargaison de fourrures à William Sublette (un peu plus de 3 800 dollars) et obtenu une licence mexicaine, Antoine Robidoux rachète le poste de Reed et Julien et y construit le fort Uintah.",
  None, "Hardee suit Barton (1993, 1996). Position au site du fort Uintah.", source=JH)
F('09', "Brown's Hole : Xavier Malona et Belcour au fort Davy Crockett (automne 1839)", 'personnage', '1839-10', -108.9, 40.87, 'a', ['Xavier Malona', 'Belcour', 'Joe Meek', 'Kit Carson'],
  "À l'automne 1839, le fort Davy Crockett, à Brown's Hole sur la Green, accueille de nombreux trappeurs libres après la chasse du printemps : Meek, Craig, Newell, Carson, Levin Mitchell, William New, Richard Owens, et deux francophones, Xavier Malona et un certain Belcour. Une trentaine partent voler des chevaux sous Joe Walker.",
  None, "Position au fort Davy Crockett (Browns Park, Colorado).", source=JH)
F('10', "Le « Robidoux's Cutoff » : la route d'Antoine Robidoux par le col Mosca", 'toponymie', '1828~/1844', -105.5, 37.73, 'a', ['Antoine Robidoux'],
  "Pour ravitailler le fort Uncompahgre, sur la Gunnison, Antoine Robidoux ouvre le « Robidoux's Cutoff » : la route quitte la piste de Santa Fe au pied de la Timpas, remonte l'Arkansas, franchit le col Mosca vers la vallée de San Luis et rejoint la branche de montagne de la Vieille piste espagnole par le col de Cochetopa. Plus courte que le détour par Santa Fe, elle évite aussi les douaniers mexicains ; selon le guide de l'excursion du symposium, elle permettait à Robidoux de contourner à la fois l'interdiction mexicaine de vendre des armes aux Indiens et l'interdiction américaine d'exporter de l'alcool en territoire indien.",
  None, "Position au col Mosca ; le guide date la fondation du fort Uncompahgre de 1828 (Reyher 2002).", source=SY)
fiches = C.fiches
